function minRungsToReachDestination(rungs, dist) {
    let n = rungs.length;
    let totalRungs = 0;

    // If no rungs are present, return 0
    if (!n) return 0;

    // Initialize start point as 0
    let i = 0;

    // Iterate through the rungs using two pointers
    while (i < n && i + 1 < n) {
        const diff = rungs[i+1] - rungs[i];

        // If difference exceeds 'dist', then we need to place a new rung
        if (diff > dist) {
            totalRungs++;

            // Insert a rung here and move both pointers forward
            i += 1; // Move past the gap
            continue;
        }

        // If it's within range, increment count by 1 and move forward
        totalRungs++;  
        i += 2; // Skip the current rung and its next
    }

    return totalRungs;
}
```

