#include <algorithm>

using namespace std;

// Function to calculate the minimum required size of a containing set
size_t minSetSize(const vector<vector<int>>& intervals) {
    // Sort intervals based on their start time
    sort(intervals.begin(), intervals.end());

    // Initialize result list
    vector<pair<int, int>> res;

    // Iterate through the sorted intervals
    for (auto& [s, e] : intervals) {
        // If current interval starts before the last selected element, add one more
        bool added = false;

        // Add only when necessary to satisfy containment requirement
        for (pair<int, int> val : res) {
            if (val.first >= s && val.second > e) {
                res.push_back({s, e});
                added = true; break;
            }
        }

        if (!added)
            res.push_back({s + 1, e});
    }

    return res.size();
}

int main() {
    vector<vector<int>> intervals = {{1, 3}, {3, 7}, {8, 9}};
    cout << minSetSize(intervals) << endl;
}
```

